def get_valid_input(prompt):
    """Get valid input from user until valid input is provided."""
    while True:
        user_input = input(prompt)
        if user_input.strip().isdigit():
            return int(user_input)
        elif user_input.strip() in ['add', 'subtract', 'multiply', 'divide']:
            return user_input.strip()
        else:
            print("Invalid input. Please enter a number or one of the following: 'add', 'subtract', 'multiply', 'divide'.")

def perform_operation(num1, num2, operation):
    """Perform the given operation on num1 and num2 and return the result."""
    if operation == 'add':
        return num1 + num2
    elif operation == 'subtract':
        return num1 - num2
    elif operation == 'multiply':
        return num1 * num2
    elif operation == 'divide':
        if num2 == 0:
            raise ValueError("Division by zero is not allowed.")
        return num1 / num2
    else:
        raise ValueError("Invalid operation. Please enter 'add', 'subtract', 'multiply', or 'divide'.")

# Get two numbers as input
num1 = get_valid_input("Enter the first number: ")
num2 = get_valid_input("Enter the second number: ")

# Get the operation to perform
operation = get_valid_input("Enter the operation (+, -, *, /): ")

# Perform the operation and print the result
result = perform_operation(num1, num2, operation)
print(f"{num1} {operation} {num2} = {result}")
